use super::*;
use serde_json::{Value,json};
use std::panic::{catch_unwind,AssertUnwindSafe};
use util::org::apache::poi::util::LittleEndianByteArrayOutput::LittleEndianByteArrayOutput;
fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");let name=["NullPointerException","RuntimeException","IllegalArgumentException"].into_iter().find(|n|s.starts_with(n)).unwrap_or(s);json!({"result":name})}}}
fn hex(b:&[u8])->String{b.iter().map(|v|format!("{v:02x}")).collect()}
fn verifier(m:&ModifyVerifier)->Value{json!({"hash":m.getHashData(),"salt":m.getSaltData(),"spin":m.getSpinCount(),"algorithm":m.getAlogrithmSid()})}
fn record(r:&FileSharingRecord)->Value{let mut a=LittleEndianByteArrayOutput::new();let serialize=call(||r.serialize(&mut a));let bytes=hex(&a.get_bytes());let mut b=LittleEndianByteArrayOutput::new();let serializez=call(||r.serializez(&mut b));json!({"readOnly":r.getReadOnly(),"password":r.getPassword(),"username":r.getUsername(),"verifier":r.getPasswordModifyVerifier().map(|m|verifier(&m.borrow())),"string":r.toString(),"sid":r.getSid(),"serialize":serialize,"bytes":bytes,"serializez":serializez,"zBytes":hex(&b.get_bytes())})}
fn one(p:&Value)->Value{let r=FileSharingRecord::new();r.setReadOnly(p["readOnly"].as_i64().unwrap()as i16);r.setPassword(p["password"].as_i64().unwrap()as i16);let m=Rc::new(RefCell::new(ModifyVerifier::new_with_algorithm__nullable(p["hash"].as_str(),p["salt"].as_str(),p["spin"].as_i64().unwrap()as i32,p["algorithm"].as_i64().unwrap()as i32)));r.setPassword__verifier(Some(m.clone()));let mut out=json!({"set":call(||{if p["value"]==true{r.setValue(p["username"].as_str());}else{r.setUsername(p["username"].as_str());}})});out["record"]=record(&r);out["clone"]=record(&r.clone());out["sameVerifier"]=json!(Rc::ptr_eq(&r.getPasswordModifyVerifier().unwrap(),&m));m.borrow_mut().setHashData("changed");m.borrow_mut().setSaltData__nullable(None);m.borrow_mut().setSpinCount(-7);m.borrow_mut().setAlogrithmSid(14);out["afterVerifierMutation"]=record(&r);r.setPassword__verifier(None);out["afterClear"]=record(&r);out}
fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}
#[test]fn original_android_file_sharing_passwords_records_and_verifier_alias(){let p=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m4-edit-save/evidence/file-sharing-r0b60");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let bmp=(0..65536).filter_map(char::from_u32).map(|c|{let s=c.to_string();json!([FileSharingRecord::hashPassword(Some(&s)),FileSharingRecord::hashPassword_Chinaese(Some(&s))])}).collect::<Vec<_>>();let hashes=input["passwords"].as_array().unwrap().iter().map(|s|json!({"hash":call(||FileSharingRecord::hashPassword(s.as_str())),"chinese":call(||FileSharingRecord::hashPassword_Chinaese(s.as_str()))})).collect::<Vec<_>>();let actual=json!({"bmp":bmp,"hashes":hashes,"records":input["records"].as_array().unwrap().iter().map(one).collect::<Vec<_>>(),"defaultRecord":record(&FileSharingRecord::new()),"defaultVerifier":verifier(&ModifyVerifier::new__nullable(None,None,0))});
 // The platform byte table is independently bound by capture SHA and verified by
 // verify-r0b60.py; exclude this platform table from the ET algorithm comparison.
 std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();let mut expected=java;expected.as_object_mut().unwrap().remove("gb2312");compare(&actual,&expected,"root");}
